from collections import Counter
class Solution:
    def numberOfPairs(self, nums):
        cnt = Counter(nums)
        pairs = leftover = 0
        for c in cnt.values():
            pairs += c // 2
            leftover += c % 2
        return [pairs, leftover]

c.cpp:
class Solution {
public:
    vector<int> numberOfPairs(vector<int>& nums) {
        int cnt[101] = {0};
        for (int x : nums) cnt[x]++;
        int pairs = 0, leftover = 0;
        for (int i = 0; i <= 100; i++) {
            pairs += cnt[i] / 2;
            leftover += cnt[i] % 2;
        }
        return {pairs, leftover};
    }
};

