class Solution {
    public int[] numberOfPairs(int[] nums) {
        int[] cnt = new int[101];
        for (int x : nums) cnt[x]++;
        int pairs = 0, leftover = 0;
        for (int c : cnt) {
            pairs += c / 2;
            leftover += c % 2;
        }
        return new int[]{pairs, leftover};
    }
}

