var numberOfPairs = function(nums) {
    const cnt = new Map();
    for (const x of nums) cnt.set(x, (cnt.get(x) || 0) + 1);
    let pairs = 0, leftover = 0;
    for (const c of cnt.values()) {
        pairs += Math.floor(c / 2);
        leftover += c % 2;
    }
    return [pairs, leftover];
};
